BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE privacy_level AS ENUM ('LOCAL_ONLY','CLOUD_ALLOWED','REDACT_BEFORE_CLOUD');
CREATE TYPE approval_status AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TABLE schema_versions(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE novels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE characters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, slug text NOT NULL, name text NOT NULL, age integer, life_status text NOT NULL DEFAULT 'ALIVE', current_location_id uuid, facts jsonb NOT NULL DEFAULT '{}', privacy privacy_level NOT NULL DEFAULT 'CLOUD_ALLOWED', UNIQUE(novel_id,slug));
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, slug text NOT NULL, name text NOT NULL, facts jsonb NOT NULL DEFAULT '{}', privacy privacy_level NOT NULL DEFAULT 'CLOUD_ALLOWED', UNIQUE(novel_id,slug));
ALTER TABLE characters ADD CONSTRAINT character_location_fk FOREIGN KEY(current_location_id) REFERENCES locations(id) ON DELETE SET NULL;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, slug text NOT NULL, name text NOT NULL, facts jsonb NOT NULL DEFAULT '{}', privacy privacy_level NOT NULL DEFAULT 'CLOUD_ALLOWED', UNIQUE(novel_id,slug));
CREATE TABLE canon_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, entity_type text NOT NULL, entity_id uuid, fact_key text NOT NULL, fact_value jsonb NOT NULL, privacy privacy_level NOT NULL DEFAULT 'CLOUD_ALLOWED', source text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(novel_id,entity_type,entity_id,fact_key));
CREATE TABLE canon_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canon_id uuid NOT NULL REFERENCES canon_entries ON DELETE CASCADE, old_value jsonb, new_value jsonb NOT NULL, source text NOT NULL, changed_at timestamptz NOT NULL DEFAULT now(), approved_by text NOT NULL);
CREATE TABLE story_states(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, chapter_number integer NOT NULL, state jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(novel_id,chapter_number));
CREATE TABLE timeline_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, event_time text NOT NULL, sequence integer NOT NULL, location_id uuid REFERENCES locations ON DELETE SET NULL, title text NOT NULL, details jsonb NOT NULL DEFAULT '{}', privacy privacy_level NOT NULL DEFAULT 'CLOUD_ALLOWED');
CREATE TABLE foreshadowing(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, title text NOT NULL, planted_chapter integer, target_chapter integer, status text NOT NULL DEFAULT 'OPEN', details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE secrets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, title text NOT NULL, content text NOT NULL, earliest_reveal_chapter integer NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', privacy privacy_level NOT NULL DEFAULT 'LOCAL_ONLY');
CREATE TABLE chapters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, chapter_number integer NOT NULL, title text, markdown_path text NOT NULL, content_hash text, workflow_status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(novel_id,chapter_number));
CREATE TABLE chapter_summaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chapter_id uuid NOT NULL REFERENCES chapters ON DELETE CASCADE, summary text NOT NULL, structured_summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pending_canon(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid NOT NULL REFERENCES novels ON DELETE CASCADE, chapter_id uuid REFERENCES chapters ON DELETE SET NULL, proposal jsonb NOT NULL, status approval_status NOT NULL DEFAULT 'PENDING', reviewed_by text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), novel_id uuid REFERENCES novels ON DELETE SET NULL, chapter_id uuid REFERENCES chapters ON DELETE SET NULL, provider text NOT NULL, model text NOT NULL, agent_role text NOT NULL, requested_at timestamptz NOT NULL DEFAULT now(), input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cached_tokens integer NOT NULL DEFAULT 0, estimated_cost numeric(12,6), status text NOT NULL, latency_ms integer, privacy_profile text NOT NULL, prompt_hash text NOT NULL, debug_summary text);
CREATE INDEX idx_canon_novel ON canon_entries(novel_id,entity_type); CREATE INDEX idx_timeline_novel ON timeline_events(novel_id,sequence); CREATE INDEX idx_pending_status ON pending_canon(novel_id,status); CREATE INDEX idx_cloud_cost ON cloud_requests(novel_id,requested_at);
INSERT INTO schema_versions(version) VALUES ('0.1.0');
COMMIT;

